package com.swiftpay.ledger.kafka; import com.fasterxml.jackson.databind.ObjectMapper; import com.swiftpay.ledger.service.SettlementService; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class SettlementListener { private final ObjectMapper mapper; private final SettlementService service; public SettlementListener(ObjectMapper m,SettlementService s){mapper=m;service=s;} @KafkaListener(topics="swiftpay.payment.initiated",groupId="ledger-service",containerFactory="kafkaListenerContainerFactory") public void onMessage(String value)throws Exception{service.settle(mapper.readValue(value,SettlementService.PaymentEvent.class));} }